action.command:
cd /workspace && php -r '
$cfg = require "config/show-garden.php";
foreach ($cfg["sensor_markers"] as $m) {
    if (isset($m["sensor"])) {
        echo $m["id"], " | sensor=", $m["sensor"], " | devEui=", $m["devEui"], "\n";
    }
}
' 2>&1

